WITH filtered AS (SELECT id, order_id, carrier, shipped_date, cost, status, CASE WHEN status = 'IN_TRANSIT' THEN 1 ELSE 0 END AS is_in_transit, CONCAT_WS('-', carrier, status) AS carrier_status_key, COALESCE(carrier, 'OTHER') AS carrier_clean FROM shipments WHERE order_id IS NOT NULL) SELECT * FROM (SELECT status, carrier, is_in_transit FROM filtered) src PIVOT (SUM(is_in_transit) AS amount, COUNT(1) AS n FOR carrier IN ('DHL' AS dhl, 'FedEx' AS fedex))
